    let c1 = Arc::clone(&c);
    let t1 = thread::spawn(move || w1(c1));

    let c2 = Arc::clone(&c);
    let t2 = thread::spawn(move || w2(c2));

    t1.join().unwrap();
    t2.join().unwrap();

    assert_eq!(c.load(Ordering::Relaxed), 2);
