    ready.recv().unwrap();
    ready.recv().unwrap();

    // Wake each waiter while holding the lock it waits on. Acquire the locks
    // separately to avoid holding both at once.
    {
        let mut finished = m1.lock().unwrap();
        *finished = true;
        cv.w1.notify_all();
    }

    {
        let mut finished = m2.lock().unwrap();
        *finished = true;
        cv.w2.notify_all();
    }
}

