use std::sync::Mutex;

pub mod main {
    use std::sync::Mutex;

    pub static a: Mutex<()> = Mutex::new(());

    pub fn t1() {
        let mut work = 0;
        let a_guard = a.lock().unwrap();
        let b_guard = crate::other::b.lock().unwrap();
        work = 1;
        drop(b_guard);
        drop(a_guard);
        let _ = work;
    }
}

pub mod other {
    use std::sync::Mutex;

    pub static b: Mutex<()> = Mutex::new(());

    pub fn t2() {
        let mut work = 0;
        let a_guard = crate::main::a.lock().unwrap();
        let b_guard = b.lock().unwrap();
        work = 1;
        drop(b_guard);
        drop(a_guard);
        let _ = work;
    }
}

fn main() {
    let t1 = std::thread::spawn(main::t1);
    let t2 = std::thread::spawn(other::t2);

    t1.join().unwrap();
    t2.join().unwrap();

    println!("DONE done=1");
}
```

